import subprocess
from pathlib import Path
Path('system').mkdir(exist_ok=True); Path('constant').mkdir(exist_ok=True)
foam_header = "FoamFile\n{\n    format ascii;\n    class dictionary;\n    object %s;\n}\n"
block_dict = foam_header % 'blockMeshDict' + r'''
convertToMeters 1;
vertices
(
    (0 0 0) (0.1 0 0) (0.1 0.06 0) (0 0.06 0)
    (0 0 0.04) (0.1 0 0.04) (0.1 0.06 0.04) (0 0.06 0.04)
);
blocks ( hex (0 1 2 3 4 5 6 7) (20 12 8) simpleGrading (1 1 1) );
edges ();
boundary
(
    adiabaticWall
    {
        type wall;
        faces
        (
            (0 4 7 3) (1 2 6 5)
            (0 1 5 4) (3 7 6 2)
            (0 3 2 1) (4 5 6 7)
        );
    }
);
mergePatchPairs ();
'''
Path('system/blockMeshDict').write_text(block_dict)
